"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useState, useEffect } from "react";
import { useAuthStore } from "../store/useAuthStore";

const navItems = [
  { label: "Overview", href: "/dashboard", icon: "📊" },
  { label: "Inventory", href: "/dashboard/inventory", icon: "📦" },
  { label: "Purchases", href: "/dashboard/purchases", icon: "🛒" },
  { label: "Selling Price", href: "/dashboard/selling-price", icon: "💰" },
  { label: "Categories", href: "/dashboard/categories", icon: "🏷️" },
  { label: "Analytics", href: "/dashboard/analytics", icon: "📈" },
  { label: "Reports", href: "/dashboard/reports", icon: "📄" },
  { label: "Settings", href: "/dashboard/settings", icon: "⚙️" }
];

export default function DashboardSidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const { logout: storeLogout } = useAuthStore();
  const [userData, setUserData] = useState(null);
  const [isExpanded, setIsExpanded] = useState(true);

  useEffect(() => {
    async function fetchUser() {
      try {
        const res = await fetch("/api/auth/me");
        const data = await res.json();
        if (data.success) {
          setUserData(data.data.user);
        }
      } catch (err) {
        console.error("Failed to fetch user", err);
      }
    }
    fetchUser();
  }, []);

  const handleLogout = async () => {
    await storeLogout();
    router.push("/auth/login");
  };

  return (
    <aside className={`hidden flex-col border-r border-border bg-card/50 text-foreground lg:fixed lg:inset-y-0 lg:left-0 lg:z-30 lg:flex transition-all duration-300 ${
      isExpanded ? "w-64 px-6 py-6 gap-6" : "w-20 px-3 py-6 gap-4"
    }`}>
      <div className="flex items-center justify-between">
        {isExpanded ? (
          <div className="flex-1">
            <p className="text-xs font-semibold uppercase tracking-[0.3em] text-primary">
              Dashboard
            </p>
            <h2 className="mt-1 text-lg font-semibold">Shopkeeper Helper</h2>
          </div>
        ) : (
          <div className="flex-1 text-center">
            <p className="text-2xl">🏪</p>
          </div>
        )}
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="ml-2 flex h-8 w-8 items-center justify-center rounded-lg hover:bg-border/50 transition"
          title={isExpanded ? "Collapse sidebar" : "Expand sidebar"}
        >
          <svg
            className="h-5 w-5 text-foreground"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            {isExpanded ? (
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
            ) : (
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
            )}
          </svg>
        </button>
      </div>
      
      <nav className="flex flex-col gap-1.5 text-sm pb-40 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center rounded-xl px-3 py-2.5 transition ${
                isActive 
                  ? "bg-primary/20 text-primary font-semibold" 
                  : "hover:bg-border/50"
              } ${isExpanded ? "gap-3" : "justify-center"}`}
              title={!isExpanded ? item.label : ""}
            >
              <span className="text-lg">{item.icon}</span>
              {isExpanded && <span>{item.label}</span>}
            </Link>
          );
        })}
      </nav>
      
      <div className={`absolute left-0 right-0 bottom-0 ${isExpanded ? "px-6 py-6" : "px-3 py-6"}`}>
        <div className={`rounded-2xl border border-border bg-card ${isExpanded ? "p-4" : "p-3"}`}>
          {isExpanded ? (
            <>
              <div className="flex items-center gap-3 mb-3">
                <div className="flex h-9 w-9 items-center justify-center rounded-full bg-primary/20 text-lg">
                  👤
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-semibold text-foreground truncate">
                    {userData?.name || "User"}
                  </p>
                  <p className="text-[10px] text-muted truncate">
                    {userData?.email || ""}
                  </p>
                </div>
              </div>
              <button
                onClick={handleLogout}
                className="w-full flex items-center justify-center gap-2 rounded-lg bg-danger/10 px-3 py-2 text-xs font-medium text-danger transition hover:bg-danger/20"
              >
                <span>🚪</span>
                <span>Logout</span>
              </button>
            </>
          ) : (
            <div className="flex flex-col items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/20 text-xl">
                👤
              </div>
              <button
                onClick={handleLogout}
                className="flex h-10 w-10 items-center justify-center rounded-lg bg-danger/10 text-lg transition hover:bg-danger/20"
                title="Logout"
              >
                🚪
              </button>
            </div>
          )}
        </div>
      </div>
    </aside>
  );
}
